tool_input.command:
$ports = 18098,18099
foreach ($p in $ports) {
  $conns = Get-NetTCPConnection -LocalPort $p -ErrorAction SilentlyContinue
  if ($conns) {
    $conns | ForEach-Object {
      $proc = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue
      Write-Output ("PORT {0} State={1} PID={2} Proc={3}" -f $p, $_.State, $_.OwningProcess, $(if($proc){$proc.ProcessName}else{'?'}))
    }
  } else {
    Write-Output ("PORT {0} : no listener" -f $p)
  }
}

$proc = Get-CimInstance Win32_Process -Filter "ProcessId=12164" -ErrorAction SilentlyContinue
Write-Output "=== Process CommandLine ==="
Write-Output $proc.CommandLine
Write-Output "=== /api/state probe ==="
try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:18098/api/state" -UseBasicParsing -TimeoutSec 8
  Write-Output ("HTTP {0}  Length={1}" -f $r.StatusCode, $r.Content.Length)
  $r.Content | Select-Object -First 1
} catch {
  Write-Output ("PROBE FAILED: {0}" -f $_.Exception.Message)
}

Write-Output "=== process 12164 alive? ==="
$p = Get-Process -Id 12164 -ErrorAction SilentlyContinue
if ($p) { Write-Output "ALIVE $($p.ProcessName)" } else { Write-Output "DEAD" }
Write-Output "=== port 18098 ==="
$c = Get-NetTCPConnection -LocalPort 18098 -State Listen -ErrorAction SilentlyContinue
if ($c) { Write-Output "LISTEN pid=$($c.OwningProcess)" } else { Write-Output "NO LISTENER" }
Write-Output "=== re-probe (longer timeout) ==="
try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:18098/api/state" -UseBasicParsing -TimeoutSec 15
  Write-Output ("HTTP {0} len={1}" -f $r.StatusCode, $r.Content.Length)
  $env:PYTHONIOENCODING='utf-8'
  $r.Content | & 'C:\Program Files\Python310\python.exe' -c "import sys,json; d=json.load(sys.stdin); print('items=',len(d['items']),' accounts=',sum(len(i.get('accounts',[])) for i in d['items']))"
} catch { Write-Output ("FAIL: {0}" -f $_.Exception.Message) }

Start-Sleep -Seconds 22
$env:PYTHONIOENCODING='utf-8'
try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:18098/api/state" -UseBasicParsing -TimeoutSec 15
  $r.Content | & 'C:\Program Files\Python310\python.exe' -c "import sys,json; d=json.load(sys.stdin); print('items=',len(d['items']),' accounts_total=',sum(len(i.get('accounts',[])) for i in d['items']))"
} catch { Write-Output ("FAIL: {0}" -f $_.Exception.Message) }

$tmpLong = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath())
$deploy = 'D:\repository\skills\deploy-env'
Write-Output "=== DRY-RUN: to be deleted ==="
$targets = @()
$audit = Join-Path $deploy 'migration-audit'
if (Test-Path $audit) { $targets += $audit; Get-ChildItem $audit -File | ForEach-Object { Write-Output ("  [audit] {0}" -f $_.FullName) } }
Get-ChildItem -Path $deploy -Filter 'registry.sqlite.*.bak' -File -ErrorAction SilentlyContinue | ForEach-Object { $targets += $_.FullName; Write-Output ("  [bak] {0}" -f $_.FullName) }
Get-ChildItem -Path $tmpLong -Filter 'dash_verify_*.png' -File -ErrorAction SilentlyContinue | ForEach-Object { $targets += $_.FullName; Write-Output ("  [shot] {0}" -f $_.FullName) }
foreach ($n in @('dash_sess.txt','dash_shot_path.txt')) {
  $p = Join-Path $env:TEMP $n
  if (Test-Path $p) { $targets += $p; Write-Output ("  [flag] {0}" -f $p) }
}
Write-Output "=== path-prefix sanity ==="
foreach ($t in $targets) {
  $okTip = $t.StartsWith($tmpLong, [System.StringComparison]::OrdinalIgnoreCase)
  $okDep = $t.StartsWith($deploy, [System.StringComparison]::OrdinalIgnoreCase)
  if (-not ($okTip -or $okDep)) { Write-Output "UNSAFE PATH: $t" } 
}
Write-Output ("total_targets={0}" -f $targets.Count)

$tmpLong = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath())
$deploy = 'D:\repository\skills\deploy-env'
# 关闭 agent-browser 会话（若仍在）
$sessFile = Join-Path $env:TEMP 'dash_sess.txt'
if (Test-Path $sessFile) {
  $sess = (Get-Content $sessFile -Raw).Trim()
  if ($sess) { agent-browser close --session $sess 2>$null | Out-Null; Write-Output "browser closed: $sess" }
}
# 删除审计目录（连目录）
$audit = Join-Path $deploy 'migration-audit'
if (Test-Path $audit) { Remove-Item -LiteralPath $audit -Recurse -Force; Write-Output "deleted audit dir" }
# 删除 bak
Get-ChildItem -Path $deploy -Filter 'registry.sqlite.*.bak' -File -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force; Write-Output ("deleted {0}" -f $_.Name) }
# 删除临时截图与 flag（长/短路径都覆盖）
Get-ChildItem -Path $tmpLong -Filter 'dash_verify_*.png' -File -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force; Write-Output ("deleted {0}" -f $_.Name) }
foreach ($n in @('dash_sess.txt','dash_shot_path.txt')) {
  $p = Join-Path $env:TEMP $n
  if (Test-Path $p) { Remove-Item -LiteralPath $p -Force; Write-Output "deleted $n" }
}
Write-Output "=== RECHECK ==="
Write-Output ("audit exists: {0}" -f (Test-Path $audit))
Write-Output ("bak count: {0}" -f @(Get-ChildItem -Path $deploy -Filter 'registry.sqlite.*.bak' -File -ErrorAction SilentlyContinue).Count)
Write-Output ("shot count: {0}" -f @(Get-ChildItem -Path $tmpLong -Filter 'dash_verify_*.png' -File -ErrorAction SilentlyContinue).Count)

try {
  $r = Invoke-WebRequest -Uri 'http://127.0.0.1:18098/api/state' -UseBasicParsing -TimeoutSec 20
  $env:PYTHONIOENCODING='utf-8'
  $r.Content | & 'C:\Program Files\Python310\python.exe' -c "import sys,json; d=json.load(sys.stdin); print('dashboard OK items=',len(d['items']),' accounts=',sum(len(i.get('accounts',[])) for i in d['items']))"
} catch { Write-Output ("dashboard FAIL: {0}" -f $_.Exception.Message) }
Write-Output "=== background jobs via job_list handled in session; no pwsh bg jobs started this hop ==="
